package com.bank.positions;

import java.math.BigDecimal;

// A lightweight risk position. Note how many REFERENCE fields it has:
// each reference is 4 bytes under compressed oops, 8 bytes without.
class Position {
    private final String tradeId;      // reference
    private final String symbol;       // reference
    private final String accountId;    // reference
    private final BigDecimal quantity; // reference
    private final BigDecimal price;    // reference
    private final BigDecimal pnl;      // reference

    Position(String tradeId, String symbol, String accountId,
             BigDecimal quantity, BigDecimal price, BigDecimal pnl) {
        this.tradeId = tradeId;
        this.symbol = symbol;
        this.accountId = accountId;
        this.quantity = quantity;
        this.price = price;
        this.pnl = pnl;
    }

    String getTradeId() { return tradeId; }
    BigDecimal getPnl() { return pnl; }
    // how many reference-shaped slots this object carries (used by estimator)
    static int referenceFieldCount() { return 6; }
}
