package com.bank.positions;

import java.lang.management.ManagementFactory;
import java.util.List;

// Reads the live JVM to report whether Compressed Oops are active.
class HeapModeInspector {

    boolean compressedOopsEnabled() {
        List<String> args = ManagementFactory.getRuntimeMXBean().getInputArguments();
        // If explicitly disabled on the command line, honour that.
        if (args.contains("-XX:-UseCompressedOops")) {
            return false;
        }
        // Heuristic matching the JVM rule: compressed oops default off above ~32GB heap.
        long maxHeapBytes = Runtime.getRuntime().maxMemory();
        long thirtyTwoGb = 32L * 1024 * 1024 * 1024;
        return maxHeapBytes <= thirtyTwoGb;
    }

    String describe() {
        return compressedOopsEnabled()
                ? "Compressed Oops ON  (references = 4 bytes)"
                : "Compressed Oops OFF (references = 8 bytes)";
    }
}
