package com.bank.positions;

// Estimates bytes per Position object under each oop mode.
class FootprintEstimator {

    // Object header: 12 bytes with compressed klass pointer, 16 bytes without.
    long bytesPerPosition(boolean compressed) {
        int refWidth = compressed ? 4 : 8;
        int header = compressed ? 12 : 16;
        long refBytes = (long) Position.referenceFieldCount() * refWidth;
        long raw = header + refBytes;
        // round up to 8-byte alignment, as the JVM does
        return ((raw + 7) / 8) * 8;
    }

    long positionsThatFit(long heapBytes, boolean compressed) {
        return heapBytes / bytesPerPosition(compressed);
    }
}
