package com.bank.positions;

import java.math.BigDecimal;
import java.util.logging.*;

public class PositionCacheDemo {
    private static final Logger log = Logger.getLogger(PositionCacheDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        HeapModeInspector inspector = new HeapModeInspector();
        FootprintEstimator estimator = new FootprintEstimator();

        log.info(() -> "JVM heap mode: " + inspector.describe());

        // Model two heaps: a safe 31GB and an over-the-line 33GB.
        long heap31 = 31L * 1024 * 1024 * 1024;
        long heap33 = 33L * 1024 * 1024 * 1024;

        long fit31 = estimator.positionsThatFit(heap31, true);   // compressed on
        long fit33 = estimator.positionsThatFit(heap33, false);  // compressed off

        log.info(() -> "31GB heap, compressed ON  -> " + fit31 + " positions fit");
        log.info(() -> "33GB heap, compressed OFF -> " + fit33 + " positions fit");

        if (fit33 < fit31) {
            log.warning(() -> "Bigger 33GB heap holds FEWER positions than 31GB! "
                    + "Crossing 32GB disabled Compressed Oops.");
        }

        // Tiny functional demo of the cache itself.
        PositionCache cache = new PositionCache();
        cache.add(new Position("TRD-001", "RELIANCE", "SAV2001",
                new BigDecimal("100"), new BigDecimal("2450.50"), new BigDecimal("1200.00")));
        log.info(() -> "Cache now holds " + cache.size() + " position(s) for the risk desk.");
    }
}

